function parseNpmRef(source) {
  const npmPart = source.slice(4)
  if (!npmPart) throw new Error(`Invalid npm reference: "${source}"`)
  let pkgName, version

  if (npmPart.startsWith('@')) {
    const slashIdx = npmPart.indexOf('/')
    if (slashIdx === -1) throw new Error(`Invalid npm reference: "${source}"`)
    const rest = npmPart.slice(slashIdx + 1)
    const at_idx = rest.indexOf('@')
    if (at_idx > 0) {
      pkgName = npmPart.slice(0, slashIdx + 1 + at_idx)
      version = rest.slice(at_idx + 1)
    } else {
      pkgName = npmPart
      version = 'latest'
    }
  } else {
    const at_idx = npmPart.lastIndexOf('@')
    if (at_idx > 0) {
      pkgName = npmPart.slice(0, at_idx)
      version = npmPart.slice(at_idx + 1)
    } else {
      pkgName = npmPart
      version = 'latest'
    }
  }

  return { pkgName, version }
}
